// 📊 COLLECTEUR - Préserve données webhook + binary
const webhookData = $input.item.json.body;

console.log('📊 COLLECTEUR:');
console.log('- Contenu reçu:', !!webhookData?.contenu);
console.log('- Taille contenu:', webhookData?.contenu?.length);
console.log('- Binary items:', $input.item.binary ? Object.keys($input.item.binary).length : 0);

if (!webhookData?.contenu) {
  throw new Error('Contenu manquant - structure: ' + JSON.stringify($input.item.json));
}

// Passer le contenu pour OpenAI ET préserver binary
return {
  json: {
    contenu_pour_openai: webhookData.contenu,
    contenu_original: webhookData.contenu,
    subtitle_original: webhookData.subtitle || '',
    collecteur_status: 'data_ready_for_openai'
  },
  binary: $input.item.binary || {}
};

// 🔗 FUSION - Combine collecteur + OpenAI en séquence
const openAIData = $input.item; // Input actuel = OpenAI
const collectorData = $input.first(); // Premier input = Collecteur

console.log('🔗 FUSION SÉQUENTIELLE:');
console.log('- OpenAI data:', !!openAIData);
console.log('- Collector data:', !!collectorData);
console.log('- OpenAI structure:', openAIData.json ? Object.keys(openAIData.json) : 'no json');

// Validation
if (!collectorData?.json?.collecteur_status) {
  throw new Error('Données collecteur manquantes');
}

if (!openAIData?.json) {
  throw new Error('Données OpenAI manquantes');
}

// Parse OpenAI - structure directe {message: {content: ...}, index: 0, finish_reason: ...}
let aiTitle = 'Titre par défaut';
let aiSubtitle = 'Sous-titre par défaut';
let aiBody = collectorData.json.contenu_original;

const aiResponse = openAIData.json.message?.content;
if (aiResponse) {
  console.log('🤖 AI RESPONSE TROUVÉE:', aiResponse.substring(0, 200));

  try {
    const cleanResponse = aiResponse.replace(/```json\n?|```\n?/g, '').trim();
    const analysis = JSON.parse(cleanResponse);

    aiTitle = analysis.title || aiTitle;
    aiSubtitle = analysis.subtitle || aiSubtitle;
    aiBody = analysis.body || aiBody;

    console.log('✅ AI PARSING SUCCESS:');
    console.log('- Title:', aiTitle);
    console.log('- Subtitle:', aiSubtitle);
  } catch (e) {
    console.log('❌ AI PARSING FAILED:', e.message);
    console.log('Raw response:', aiResponse);
  }
} else {
  console.log('❌ Pas de message.content dans OpenAI');
  console.log('Structure OpenAI:', JSON.stringify(openAIData.json));
}

// Résultat final avec binary du collecteur
const result = {
  json: {
    // Données analysées par IA
    ai_title: aiTitle,
    ai_subtitle: aiSubtitle,
    ai_body: aiBody,

    // Données originales
    contenu_original: collectorData.json.contenu_original,
    subtitle_original: collectorData.json.subtitle_original,

    // Debug
    debug: {
      collector_found: true,
      openai_found: true,
      ai_parsing_success: aiTitle !== 'Titre par défaut',
      binary_preserved: !!(collectorData.binary && Object.keys(collectorData.binary).length > 0),
      binary_count: collectorData.binary ? Object.keys(collectorData.binary).length : 0,
      workflow_type: 'sequential'
    }
  },
  binary: collectorData.binary || {}
};

console.log('🎯 FUSION RESULT:');
console.log('- Final AI Title:', result.json.ai_title);
console.log('- Binary preserved:', result.json.debug.binary_preserved);

return result;

// ✅ RÉSULTAT FINAL
const flaskResponse = $input.item.json;
const fusionData = $input.first();

if (flaskResponse?.success) {
  return {
    json: {
      status: 'success',
      message: '🎉 Document créé avec IA séquentielle !',
      project_id: flaskResponse.project_id,
      download_url: `http://host.docker.internal:5003/api/download/${flaskResponse.project_id}`,

      ai_content: {
        title: fusionData?.json?.ai_title,
        subtitle: fusionData?.json?.ai_subtitle,
        body_preview: fusionData?.json?.ai_body?.substring(0, 100) + '...'
      },

      technical: fusionData?.json?.debug
    }
  };
}

return {
  json: {
    status: 'error',
    error: flaskResponse?.error || 'Erreur Flask',
    debug: { flask_response: flaskResponse, fusion_debug: fusionData?.json?.debug }
  }
};
